class Solution {
public:
    int minimumPartition(std::string s, int k) {
        int ans = 0;
        long long cur = 0;
        for (char ch : s) {
            int d = ch - '0';
            if (d > k) return -1;
            if (cur * 10 + d <= k) {
                cur = cur * 10 + d;
            } else {
                ans++;
                cur = d;
            }
        }
        if (cur > 0) ans++;
        return ans;
    }
};

class Solution {
    public int minimumPartition(String s, int k) {
        int ans = 0;
        long cur = 0;
        for (int i = 0; i < s.length(); i++) {
            int d = s.charAt(i) - '0';
            if (d > k) return -1;
            if (cur * 10 + d <= k) {
                cur = cur * 10 + d;
            } else {
                ans++;
                cur = d;
            }
        }
        if (cur > 0) ans++;
        return ans;
    }
}

var minimumPartition = function(s, k) {
    let ans = 0;
    let cur = 0;
    for (let i = 0; i < s.length; i++) {
        const d = Number(s[i]);
        if (d > k) return -1;
        if (cur * 10 + d <= k) {
            cur = cur * 10 + d;
        } else {
            ans++;
